        return d_ExpandedWindowToolbarStyle(v)
    case 2486, 2487, 2729, 2730:
        return d_UnifiedCompactWindowToolbarStyle(v)
    case 2488, 2489, 2732, 2733:
        return d_UnifiedWindowToolbarStyle(v)
    default: return nil
    }
}
#endif
